/**
 * useCategories Hook
 *
 * Custom hook for managing category CRUD operations and state.
 * Provides methods for fetching, creating, updating, and deleting categories.
 *
 * Usage:
 *   const { categories, isLoading, error, fetchCategories, createCategory, updateCategory, deleteCategory } = useCategories(organizationId)
 */

import { useState, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { Category } from '@/types/database'

/**
 * Category form data interface
 */
export interface CategoryFormData {
  name: string
  slug?: string
  parent_id?: string | null
  sort_order?: number
  is_visible?: boolean
}

/**
 * Hook return type
 */
export interface UseCategoriesReturn {
  categories: Category[]
  isLoading: boolean
  error: string | null
  fetchCategories: () => Promise<void>
  createCategory: (data: CategoryFormData) => Promise<string>
  updateCategory: (id: string, data: CategoryFormData) => Promise<void>
  deleteCategory: (id: string) => Promise<void>
  toggleVisibility: (id: string, isVisible: boolean) => Promise<void>
}

/**
 * Custom hook for category management
 *
 * @param organizationId - The organization ID to fetch categories for
 * @returns Category state and CRUD methods
 */
export function useCategories(organizationId: string | undefined): UseCategoriesReturn {
  const [categories, setCategories] = useState<Category[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  /**
   * Fetch categories from the database
   */
  const fetchCategories = useCallback(async () => {
    if (!organizationId) return

    setIsLoading(true)
    setError(null)

    try {
      const supabase = createClient()

      const { data: categoriesData, error: categoriesError } = await supabase
        .from('categories')
        .select('*')
        .eq('organization_id', organizationId)
        .order('sort_order', { ascending: true })

      if (categoriesError) throw categoriesError

      setCategories(categoriesData || [])
    } catch (err) {
      setError('Failed to fetch categories')
    } finally {
      setIsLoading(false)
    }
  }, [organizationId])

  /**
   * Create a new category
   */
  const createCategory = useCallback(async (data: CategoryFormData): Promise<string> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const categoryData = {
      name: data.name.trim(),
      slug: data.slug?.trim() || null,
      parent_id: data.parent_id || null,
      sort_order: data.sort_order ?? 0,
      is_visible: data.is_visible ?? true,
      organization_id: organizationId,
    }

    const { data: newCategory, error: insertError } = await supabase
      .from('categories')
      .insert(categoryData)
      .select()
      .single()

    if (insertError) throw insertError

    return newCategory.id
  }, [organizationId])

  /**
   * Update an existing category
   */
  const updateCategory = useCallback(async (id: string, data: CategoryFormData): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const categoryData = {
      name: data.name.trim(),
      slug: data.slug?.trim() || null,
      parent_id: data.parent_id || null,
      sort_order: data.sort_order ?? 0,
      is_visible: data.is_visible ?? true,
    }

    const { error: updateError } = await supabase
      .from('categories')
      .update(categoryData)
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (updateError) throw updateError
  }, [organizationId])

  /**
   * Delete a category
   */
  const deleteCategory = useCallback(async (id: string): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const { error: deleteError } = await supabase
      .from('categories')
      .delete()
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (deleteError) throw deleteError
  }, [organizationId])

  /**
   * Toggle category visibility
   */
  const toggleVisibility = useCallback(async (id: string, isVisible: boolean): Promise<void> => {
    if (!organizationId) throw new Error('Organization ID is required')

    const supabase = createClient()

    const { error: updateError } = await supabase
      .from('categories')
      .update({ is_visible: isVisible })
      .eq('id', id)
      .eq('organization_id', organizationId)

    if (updateError) throw updateError
  }, [organizationId])

  return {
    categories,
    isLoading,
    error,
    fetchCategories,
    createCategory,
    updateCategory,
    deleteCategory,
    toggleVisibility,
  }
}
